<template><section class="card"><h1>내 프로필</h1><form class="form" @submit.prevent="save"><div class="field"><label>닉네임</label><input v-model="form.nickname"></div><div class="field"><label>소개</label><textarea v-model="form.bio" rows="4"></textarea></div><div class="field"><label>이미지</label><input type="file" accept="image/*" @change="e=>file=e.target.files[0]"></div><button>저장</button></form><p class="success" v-if="message">{{message}}</p></section></template>
<script setup>import { onMounted, reactive, ref } from 'vue'; import api from '@/api/axios'; const form=reactive({nickname:'',bio:''}); const file=ref(null); const message=ref(''); const load=async()=>{const r=await api.get('/api/v1/profiles/me/'); form.nickname=r.data.nickname; form.bio=r.data.bio}; const save=async()=>{const fd=new FormData(); fd.append('nickname',form.nickname); fd.append('bio',form.bio); if(file.value) fd.append('image',file.value); await api.patch('/api/v1/profiles/me/',fd,{headers:{'Content-Type':'multipart/form-data'}}); message.value='저장 완료'}; onMounted(load)</script>
